/* Интерфейс, создание персонажа и игровой цикл. */
(function(){
  const app=document.getElementById('app');
  const topbar=document.getElementById('topbar');
  const topStatus=document.getElementById('top-status');
  const footer=document.getElementById('site-footer');
  let tab='world';
  let showTeamDetails=false;
  let pendingAvatar='';
  let notice='';
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const $=(id)=>document.getElementById(id);
  const s=()=>OD_STATE.get();
  const player=()=>s().player;
  const factionOptions=type=>type==='Человек'?['БПСД','Без фракции']:['БПСД','Орден','Без фракции'];
  const factionDescription=f=>f==='БПСД'?'Бюро по сопротивлению духов — структура, расследующая дела, связанные с одержимыми, ходячими и аномальными происшествиями.':f==='Орден'?'Тайная организация одержимых, стремящаяся подчинить себе мир. Люди не могут вступить в Орден.':'Вы не состоите в организациях и сами выбираете, как жить и зарабатывать.';
  function setNotice(msg){notice=msg;}
  const dateLabel=st=>`${String(st.calendar?.date||1).padStart(2,'0')}.${String(st.calendar?.month||9).padStart(2,'0')}.${st.calendar?.year||2023}`;
  function render(){
    const st=s();
    const inGame=st.step==='game'||st.step==='briefing';
    topbar.hidden=!inGame;footer.hidden=inGame;
    if(inGame){topStatus.innerHTML=`<span>${dateLabel(st)} · ${String(st.hour).padStart(2,'0')}:${String(st.minute).padStart(2,'0')}</span><span>${esc(st.money)} €</span><span>${esc(st.player?.faction||'Без фракции')}</span>`;}
    if(st.step==='landing')app.innerHTML=renderLanding();
    else if(st.step==='type')app.innerHTML=renderType();
    else if(st.step==='dossier')app.innerHTML=renderDossier();
    else if(st.step==='start')app.innerHTML=renderStart();
    else if(st.step==='interview')app.innerHTML=renderInterview();
    else if(st.step==='briefing')app.innerHTML=renderBriefing();
    else app.innerHTML=renderGame();
    if(notice){const n=document.createElement('div');n.className='toast';n.textContent=notice;document.body.appendChild(n);setTimeout(()=>n.remove(),2600);notice='';}
  }
  function renderLanding(){return `<section class="landing-page"><div class="hero-kicker">BERLIN · CLASSIFIED CASE FILES · 2023</div><div class="hero-title"><span>ОДЕРЖИМЫЕ</span><i>THE POSSESSED</i></div><p class="hero-copy">После физиологической смерти тело может стать домом для чужого духа. В городе, где граница между человеком и чудовищем стала тоньше бумаги, каждый выбор оставляет след.</p><div class="entry-rule"><span></span><small>ВЫБЕРИТЕ СВОЮ ПРИРОДУ</small><span></span></div><div class="choice-grid">
    <button class="choice-card human-card" data-action="choose-human"><img src="https://i.pinimg.com/736x/08/94/c2/0894c2f68fbe4cf364ed538a58c27c19.jpg" referrerpolicy="no-referrer" loading="eager" alt="Человек"><span class="choice-number">01 / HUMAN</span><strong>Человек</strong><small>Смертный. Уязвимый. Свободный.</small><b>ВЫБРАТЬ <i>→</i></b></button>
    <button class="choice-card possessed-card" data-action="choose-possessed"><img src="https://i.pinimg.com/1200x/96/a3/19/96a3193002edf9646a59ae160e65595b.jpg" referrerpolicy="no-referrer" loading="eager" alt="Одержимый"><span class="choice-number">02 / POSSESSED</span><strong>Одержимый</strong><small>Смерть — не конец. Дух — не подарок.</small><b>ВЫБРАТЬ <i>→</i></b></button>
    </div><div class="landing-bottom"><span>ОФЛАЙН-РОЛЕВАЯ СИСТЕМА</span><span>НЕЗАВИСИМОЕ СОХРАНЕНИЕ В БРАУЗЕРЕ</span></div></section>`;}
  function renderType(){const type=s().characterType;const human=type==='Человек';return `<section class="document-page narrow"><div class="eyebrow">КЛАССИФИКАЦИЯ СУБЪЕКТА · ${human?'H-01':'P-02'}</div><div class="doc-heading"><span class="doc-number">${human?'01':'02'}</span><div><h1>${human?'Человек':'Одержимый'}</h1><p>${human?'HUMAN / MORTAL':'POSSESSED / SPIRIT HOST'}</p></div></div><div class="paper-copy">${human?'<p>Обычный представитель человечества, обладающий естественными физическими и умственными способностями. Уязвим к обычным травмам и болезням, стареет и нуждается в пище, воде и отдыхе. Не обладает сверхъестественными способностями.</p>':'<p>Человек, чьё тело захватил дух после физиологической смерти. Обладает сверхчеловеческой силой, выносливостью и регенерацией, а также уникальным Даром, связанным с природой духа. Не стареет, но нуждается в особом питании, содержащем достаточное количество минералов для регенерации и использования Даров. Каждый одержимый имеет характерную метку на теле, отражающую природу его духа.</p>'}</div><div class="type-facts"><div><small>СТАТУС</small><strong>${human?'Смертный':'Посмертный носитель'}</strong></div><div><small>ОСОБЫЕ СПОСОБНОСТИ</small><strong>${human?'Отсутствуют':'Один уникальный Дар'}</strong></div><div><small>ПОТРЕБНОСТИ</small><strong>${human?'Пища · вода · отдых':'Минералы · вода · отдых'}</strong></div></div><div class="button-row"><button class="btn secondary" data-action="back-landing">← Назад</button><button class="btn primary" data-action="to-dossier">Далее →</button></div></section>`;}
  function renderDossier(){const type=s().characterType;const opts=factionOptions(type);const home=OD_DATA.locations.filter(l=>l.kind==='house');const image=pendingAvatar||'';return `<section class="dossier-wrap"><div class="file-top"><div><div class="eyebrow">BPSD / PERSONNEL ARCHIVE · FORM 07-B</div><h1>Личное досье</h1><p>Заполните данные субъекта. Поля с отметкой * обязательны.</p></div><div class="stamp">${type==='Человек'?'HUMAN':'POSSESSED'}<br><b>ПРОВЕРЕНО</b></div></div><form id="dossier-form" class="dossier-paper"><div class="paper-watermark">ARCHIVE</div><div class="dossier-main-grid"><div class="portrait-column"><div class="portrait-frame"><div id="portrait-empty" class="portrait-empty" ${image?'hidden':''}>ПОРТРЕТ НЕ ДОБАВЛЕН</div><img id="portrait-preview" src="${image}" alt="Внешность персонажа" ${image?'':'hidden'}></div><label class="field-label">ССЫЛКА НА ИЗОБРАЖЕНИЕ</label><input type="url" name="imageUrl" id="image-url" placeholder="https://..." value="${esc(image.startsWith('http')?image:'')}"><label class="file-pick">Загрузить изображение с устройства<input type="file" id="image-file" accept="image/*"></label><small class="field-hint">Изображение можно загрузить с телефона или ноутбука. Оно будет сохранено локально.</small></div><div class="fields-column"><div class="section-label">I. ЛИЧНЫЕ ДАННЫЕ</div><div class="field-grid two"><label>Имя *<input name="firstName" required maxlength="30" placeholder="Например, Алекс"></label><label>Фамилия *<input name="lastName" required maxlength="40" placeholder="Например, Вебер"></label><label>Возраст *<input type="number" name="age" required min="16" max="120" value="25"></label><label>Вес (кг)<input type="number" name="weight" min="35" max="250" value="78"></label><label>Рост (см)<input type="number" name="height" min="120" max="230" value="180"></label><label>Страна<select name="country">${OD_DATA.countries.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>Начальная специализация<select name="specialization"><option>Универсал</option><option>Ближний бой</option><option>Скрытность</option><option>Медицина</option><option>Аналитика</option><option>Следопытство</option><option>Переговоры</option></select></label></div><label>Характер *<textarea name="nature" required rows="2" placeholder="Черты характера, привычки, страхи..."></textarea></label><label>Биография *<textarea name="bio" required rows="4" placeholder="Кем вы были до начала истории? Что привело вас в Берлин?"></textarea></label><div class="section-label">II. ПРИНАДЛЕЖНОСТЬ</div><label>Фракция<select name="faction" id="faction-select">${opts.map(x=>`<option>${x}</option>`).join('')}</select></label><p class="field-hint" id="faction-note">${esc(factionDescription(opts[0]))}</p>${type==='Одержимый'?`<div class="section-label">III. ПАРАМЕТРЫ ДУХА</div><div class="field-grid two"><label>Дух *<input type="text" name="spirit" id="spirit-input" maxlength="60" required placeholder="Введите любое имя или название духа"></label><label>Дар / способность<input name="gift" id="gift-input" maxlength="120" required placeholder="Опишите уникальный Дар"></label></div><label>Метка на теле<input name="mark" id="mark-input" maxlength="160" required placeholder="Опишите характерную метку"></label><p class="field-hint">Можно вписать любого нового духа — списка ограниченных вариантов нет. У одного духа может быть только один носитель: либо одержимый человек, либо ходячее животное. Обычно у одержимого один основной Дар.</p>`:''}<div class="section-label">${type==='Одержимый'?'IV':'III'}. ИМУЩЕСТВО И БЫТ</div><div class="field-grid two"><label>Место жительства<select name="home" id="home-select" ${type==='Одержимый'?'disabled':''}><option value="">Не указано</option>${home.map(h=>`<option value="${h.id}">${esc(h.name)}</option>`).join('')}</select></label><label>Автомобиль<input name="car" placeholder="Нет / марка и модель"></label><label>Оружие<input name="weapon" placeholder="Например, Glock 17 / нет"></label><label>Деньги (€)<input type="number" name="money" min="0" max="100000" value="250"></label></div><div class="field-hint warning-note" id="home-rule">У одержимого сотрудника БПСД нет личного жилья: ему предоставляется служебное размещение. Члены Ордена живут в логове.</div></div></div><div class="dossier-bottom"><span>ПЕРСОНАЛЬНОЕ ДЕЛО · НЕ ДЛЯ ПУБЛИЧНОГО ДОСТУПА</span><button class="btn primary" type="submit">Сохранить досье →</button></div></form><button class="text-back" data-action="back-type">← Вернуться к описанию</button></section>`;}
  function renderStart(){const p=player();const fac=p.faction;return `<section class="document-page narrow"><div class="eyebrow">ЛИЧНОЕ ДЕЛО ПРИНЯТО · СЛЕДУЮЩИЙ ЭТАП</div><h1>Выберите начало истории</h1><p class="muted">${esc(p.name)} · ${esc(p.type)} · ${esc(fac)}</p>${fac==='БПСД'?`<div class="start-grid"><button class="start-card" data-action="start-early"><span>01 / РАННИЙ СТАРТ</span><strong>Допрос и распределение</strong><p>Вас вызывают в отдел БПСД. Несколько вопросов, оценка навыков и направление в один из отрядов. После распределения вы отправитесь знакомиться с командой.</p><b>НАЧАТЬ РАНЬШЕ →</b></button><button class="start-card" data-action="start-late"><span>02 / ПОЗДНИЙ СТАРТ</span><strong>Уже в отряде</strong><p>Вы просыпаетесь в доме или служебном помещении своего отряда. Команда уже знает вас, а дела идут своим чередом.</p><b>НАЧАТЬ ПОЗЖЕ →</b></button></div>`:fac==='Орден'?`<div class="start-card order-start"><span>ОРДЕН · ЗАКРЫТЫЙ ДОСТУП</span><strong>Логово Вара</strong><p>Вы появляетесь в тайном подземном комплексе за пределами Берлина. Одержимые Вара готовят захват власти и считают человечество препятствием.</p><button class="btn primary" data-action="start-order">Войти в логово →</button></div>`:`<div class="start-card"><span>БЕЗ ФРАКЦИИ</span><strong>Своя жизнь в Берлине</strong><p>Вы не связаны обязательствами перед БПСД или Орденом. Можно арендовать жильё, искать работу, общаться с жителями и постепенно выяснять, что происходит в городе.</p><button class="btn primary" data-action="start-free">Начать жизнь →</button></div>`}<button class="text-back" data-action="back-dossier">← Вернуться к анкете</button></section>`;}
  function renderInterview(){const p=player();return `<section class="interview-wrap"><div class="eyebrow">BPSD · DEPARTMENT 02 · INTERROGATION ROOM</div><div class="interview-header"><div><h1>Первичный допрос</h1><p>Ваши ответы, навыки и природа Духа повлияют на распределение. Отряд выбирается с небольшой долей случайности.</p></div><div class="interview-subject">SUBJECT<br><strong>${esc(p.name)}</strong><small>${esc(p.type)} · ${esc(p.spirit||'человек')}</small></div></div><div class="interview-scene"><div class="scene-label">СЛЕДОВАТЕЛЬ / 08:42</div><p>«Садитесь. Не будем тратить время. Нам нужно понять, как вы действуете под давлением. Отвечайте честно — идеальных ответов не существует».</p></div><form id="interview-form" class="interview-form"><label><span>ВОПРОС 01</span>Вы замечаете человека с неизвестной меткой, который ведёт себя подозрительно. Ваши действия?<textarea name="q1" rows="2" placeholder="Ваш ответ..."></textarea></label><label><span>ВОПРОС 02</span>Во время операции напарник оказывается в опасности, но приказ требует удерживать позицию. Что будете делать?<textarea name="q2" rows="2" placeholder="Ваш ответ..."></textarea></label><label><span>ВОПРОС 03</span>Какой подход вам ближе: прямое столкновение, осторожное наблюдение, помощь людям или планирование операции?<textarea name="q3" rows="2" placeholder="Ваш ответ..."></textarea></label><div class="button-row"><button type="button" class="btn secondary" data-action="back-start">← Назад</button><button class="btn primary" type="submit">Завершить допрос и получить назначение →</button></div></form></section>`;}
  function teamById(id){return [...OD_DATA.humanTeams,...OD_DATA.mixedTeams,...OD_DATA.possessedTeams].find(t=>t.id===id)||null;}
  function memberName(id){if(id==='player')return player()?.name||'Игрок';const h=OD_DATA.humanNPCs.find(x=>x.id===id);if(h)return h.name;const p=OD_DATA.possessed.find(x=>x.id===id);return p?.name||'Неизвестный участник';}
  function memberDetails(id){if(id==='player')return player()?.type||'Игрок';const h=OD_DATA.humanNPCs.find(x=>x.id===id);if(h)return h.role;const p=OD_DATA.possessed.find(x=>x.id===id);return p?`Одержимый · ${p.spirit}`:'Участник';}
  function teamCard(){const st=s();const t=teamById(st.teamId);if(st.player.faction==='Орден')return `<div class="team-card"><div class="team-title"><span>ОРДЕН</span><h2>Последователи Вара</h2></div><p>Вас направили в тайное логово. Руководитель — Вар, одержимый духом Войны. В Орден принимают только одержимых.</p><div class="team-members"><div><b>Вар</b><small>Лидер Ордена · дух Войны</small></div><div><b>Старшие последователи</b><small>Одержимые бойцы и идеологи</small></div><div><b>${esc(st.player.name)}</b><small>Новый участник Ордена</small></div></div></div>`;
    if(!t)return `<div class="team-card"><h2>Без отряда</h2><p>Вы действуете самостоятельно.</p></div>`;
    const ids=st.teamId===t.id&&st.teamOverride?(t.type==='mixed'?[...st.teamOverride,t.leader]:t.type==='possessed'?[t.leader,...st.teamOverride]:st.teamOverride):(t.type==='mixed'?[...t.members,t.leader]:t.type==='possessed'?[t.leader,...t.members]:t.members);
    return `<div class="team-card"><div class="team-title"><span>${esc(t.id)} · ${t.type==='human'?'ЧЕЛОВЕЧЕСКИЙ':'ОДЕРЖИМЫЕ'}</span><h2>Отряд «${esc(t.name)}»</h2></div><p>${esc(t.description)}</p><div class="team-members">${ids.map(id=>`<div><b>${esc(memberName(id))}</b><small>${esc(memberDetails(id))}${id===t.leader?' · командир':''}</small></div>`).join('')}</div></div>`;}
  function renderBriefing(){const st=s();return `<section class="briefing-page"><div class="eyebrow">BPSD · PERSONNEL ASSIGNMENT</div><h1>Назначение завершено</h1><p class="muted">${esc(st.player.name)}, ваше дело внесено в архив. Ознакомьтесь с составом.</p>${teamCard()}<div class="briefing-bottom"><p>Вас ожидает транспорт. Следующая точка — служебный дом и знакомство с отрядом.</p><button class="btn primary" data-action="arrive-team">Отправиться к отряду →</button></div></section>`;}
  function statBar(label,value){return `<div class="need-row"><div><span>${label}</span><b>${Math.round(value)}%</b></div><div class="need-track"><i style="width:${Math.max(0,Math.min(100,value))}%"></i></div></div>`;}
  function renderGame(){const st=s();const p=st.player;const views={world:renderWorld,map:renderMap,character:renderCharacter,inventory:renderInventory,combat:renderCombat,jobs:renderJobs,training:renderTraining,devices:renderDevices,settings:renderSettings};const content=(views[tab]||renderWorld)();return `<div class="game-layout"><aside class="sidebar"><div class="side-character">${p.image?`<div class="side-avatar"><img src="${esc(p.image)}" alt=""></div>`:''}<div><strong>${esc(p.name)}</strong><small>${esc(p.type)} · ${esc(p.faction)}</small></div></div><nav class="side-nav">${[['world','◈','RP / Сцена'],['map','⌖','Карта'],['character','▤','Персонаж'],['inventory','▣','Инвентарь'],['devices','▣','Устройства'],['combat','⚔','Столкновения'],['jobs','₠','Экономика'],['training','↗','Тренировки'],['settings','⚙','Система']].map(([id,icon,name])=>`<button class="nav-link ${tab===id?'active':''}" data-tab="${id}"><span>${icon}</span>${name}</button>`).join('')}</nav><div class="sidebar-bottom"><small>ДЕЛО № ${String(p.firstName||'').slice(0,2).toUpperCase()}-${String(st.day).padStart(3,'0')}</small><button data-action="save" class="save-mini">Сохранить прогресс</button></div></aside><section class="game-main"><div class="mobile-nav">${[['world','RP'],['map','Карта'],['character','Персонаж'],['inventory','Вещи'],['devices','Устройства'],['combat','Бой'],['jobs','Экономика'],['training','Тренировки'],['settings','Система']].map(([id,name])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${name}</button>`).join('')}</div>${content}</section><aside class="right-rail"><div class="rail-card"><div class="rail-head">СОСТОЯНИЕ</div>${statBar('Здоровье',st.needs.health)}${statBar('Энергия',st.needs.energy)}${statBar('Голод',st.needs.hunger)}${statBar('Жажда',st.needs.thirst)}${statBar('Рассудок',st.needs.sanity)}${st.player.type==='Одержимый'?statBar('Минералы',st.needs.minerals):''}</div><div class="rail-card"><div class="rail-head">ТЕКУЩЕЕ МЕСТО</div><strong>${esc(OD_WORLD.getPlace(st.location)?.name||'Неизвестно')}</strong><p class="tiny-muted">${esc(OD_WORLD.getPlace(st.location)?.description||'')}</p></div><div class="rail-card"><div class="rail-head">ПОСЛЕДНИЕ СОБЫТИЯ</div><div class="mini-log">${st.log.slice(0,4).map(x=>`<p>${esc(x)}</p>`).join('')}</div></div></aside></div>`;}
  function renderWorld(){const st=s(),p=OD_WORLD.getPlace(st.location),team=teamById(st.teamId),exits=OD_WORLD.getLocalExits(),turns=(st.rpTurns||[]).slice(-9);const f=OD_WORLD.featuresAt();const options=[['fridge','Открыть холодильник','Открываю холодильник'],['bed','Лечь отдохнуть','Ложусь на кровать и отдыхаю'],['shower','Принять душ','Принимаю душ'],['laptop','Открыть ноутбук','Открываю ноутбук'],['computer','Сесть за компьютер','Сажусь за рабочий компьютер'],['moped-park','Осмотреть стоянку мопедов','Осматриваю припаркованные мопеды']].filter(x=>f.includes(x[0]));return `<div class="page-head"><div><div class="eyebrow">BERLIN · TEXT ROLEPLAY · 2023</div><h1>Ролевая сцена</h1><p>${dateLabel(st)} · ${String(st.hour).padStart(2,'0')}:${String(st.minute).padStart(2,'0')} · ${esc(p?.name||'Берлин')}</p></div><span class="status-tag">${st.player.faction==='БПСД'?'СЛУЖБА':st.player.faction==='Орден'?'ОРДЕН':'СВОБОДНАЯ ЖИЗНЬ'}</span></div><div class="world-hero"><div class="world-hero-copy"><span class="eyebrow">ТЕКУЩАЯ ЛОКАЦИЯ</span><h2>${esc(p?.name||'Берлин')}</h2><p>${esc(p?.description||'Вы находитесь в городе.')} Мастер учитывает, где вы находитесь: доступные действия зависят от помещения.</p><div class="quick-actions"><button data-action="eat">Поесть</button><button data-action="drink">Выпить</button>${(f.includes('bed')||f.includes('sofa'))?'<button data-action="rest">Отдохнуть</button>':''}${f.includes('people')?'<button data-action="talk">Поговорить</button>':''}<button data-action="explore">Осмотреться</button></div></div><div class="world-stamp"><span>BERLIN</span><b>RP<br>2023</b><small>SCENE / ${String(st.day).padStart(2,'0')}</small></div></div>${team?`<div class="inline-team"><div><span class="eyebrow">ВАШ ОТРЯД</span><strong>${esc(team.name)} · ${esc(team.id)}</strong><small>${esc(team.description)}</small></div><button class="btn secondary small" data-action="team-details">${showTeamDetails?'Скрыть состав ↑':'Состав →'}</button></div>`:st.player.faction==='Орден'?`<div class="inline-team order-inline"><div><span class="eyebrow">ОРДЕН</span><strong>Логово Вара</strong><small>Ваши цели определяются руководством Ордена.</small></div></div>`:''}${showTeamDetails&&team?teamCard():''}${st.encounter?`<div class="encounter-card"><div><span class="eyebrow">ОБНАРУЖЕННЫЙ ПЕРСОНАЖ / ЦЕЛЬ</span><strong>${esc(st.encounter.name)}</strong><p>${esc(st.encounter.description||'Противник пока не атакует.')}</p><small>Столкновение ещё не началось. Решение о нападении остаётся за игроком.</small></div><button class="btn secondary" data-rp-action="Отступаю от противника и ухожу на безопасное расстояние">Отойти</button></div>`:''}<div class="section-heading"><h2>Локальные переходы</h2><span>ТОЛЬКО ДОСТУПНЫЕ МЕСТА</span></div><div class="local-exits">${exits.length?exits.map(l=>`<button class="local-exit" data-travel="${l.id}"><span>${placeIcon(l.kind)}</span><b>${esc(l.name)}</b><small>${esc(l.description)}</small><i>Перейти →</i></button>`).join(''):'<p class="muted">Рядом нет доступных переходов. Откройте карту, чтобы выбрать городской маршрут.</p>'}</div>${options.length?`<div class="section-heading"><h2>Действия в этом помещении</h2><span>КОНТЕКСТ ЛОКАЦИИ</span></div><div class="context-actions">${options.map(([id,label,action])=>`<button data-rp-action="${action}">${label}</button>`).join('')}</div>`:''}<div class="section-heading"><h2>Действие игрока</h2><span>GM ROLEPLAY · FREE TEXT</span></div><div class="rp-explainer">Вы описываете, что делаете или говорите. Мастер отыгрывает NPC, окружение и последствия. Сложные действия не считаются успешными автоматически.</div><form class="action-console" id="free-action-form"><div class="console-top"><span>›</span><small>Ваш ход</small><kbd>RP</kbd></div><textarea name="action" rows="3" placeholder="Например: Я поправляю куртку, выхожу из кухни в коридор и спрашиваю соседа, слышал ли он ночной шум..." required></textarea><button class="btn primary" type="submit">Отправить ход мастеру →</button></form><div class="section-heading"><h2>Ход ролевой сцены</h2><span>ИГРОК / МАСТЕР</span></div><div class="rp-transcript">${turns.length?turns.map(t=>`<article class="rp-turn ${t.kind==='intro'?'rp-intro':''}">${t.action?`<div class="rp-player"><small>ИГРОК · ${esc(t.time||'')}</small><p>${esc(t.action)}</p></div>`:''}<div class="rp-gm"><small>МАСТЕР · ${esc(t.time||'')||'ВСТУПЛЕНИЕ'}</small><p>${esc(t.reply)}</p></div></article>`).join(''):'<p class="muted">Начальная сцена ещё не создана.</p>'}</div><div class="section-heading"><h2>Журнал мира</h2><span>ПОСЛЕДНИЕ СОБЫТИЯ</span></div><div class="event-list">${st.log.slice(0,5).map(x=>`<div class="event-row"><i></i><p>${esc(x)}</p></div>`).join('')}</div>`;}
  function placeIcon(kind){return ({office:'▣',cafe:'☕',restaurant:'◉',bowling:'●',darts:'◎',stadium:'▤',landmark:'◆',house:'⌂',order:'◈',street:'↗',district:'⌖',industrial:'⚙',underpass:'▿',alley:'↘',danger:'!'}[kind]||'•');}
  function renderMap(){const current=s().location;const locs=OD_WORLD.visibleLocations();return `<div class="page-head"><div><div class="eyebrow">CITY GRID / BERLIN AREA</div><h1>Карта города</h1><p>Схематичная карта районов, улиц и игровых точек. Нажмите на метку или выберите место в списке.</p></div><span class="status-tag">${locs.length} ТОЧЕК</span></div><div class="map-layout"><div class="map-frame">${OD_WORLD.mapSVG()}<div class="map-compass">N<br>↑</div><div class="map-caption">BERLIN · 2023 · LOCAL MAP · NOT TO SCALE</div></div><div class="map-side"><div class="map-current"><small>ТЕКУЩАЯ ЛОКАЦИЯ</small><strong>${esc(OD_WORLD.getPlace(current)?.name||'')}</strong><p>${esc(OD_WORLD.getPlace(current)?.description||'')}</p></div><div class="place-filter"><button class="${s().mapFilter==='all'?'active':''}" data-filter="all">Все</button><button class="${s().mapFilter==='office'?'active':''}" data-filter="office">БПСД</button><button class="${s().mapFilter==='leisure'?'active':''}" data-filter="leisure">Досуг</button></div><div class="place-list">${locs.filter(l=>{const f=s().mapFilter;return f==='all'||(f==='office'?l.kind==='office':['cafe','restaurant','bowling','darts','stadium','landmark'].includes(l.kind));}).map(l=>`<button class="place-item ${current===l.id?'current':''}" data-travel="${l.id}"><span>${placeIcon(l.kind)}</span><div><b>${esc(l.name)}</b><small>${esc(l.description)}</small></div><i>${current===l.id?'ЗДЕСЬ':'→'}</i></button>`).join('')}</div></div></div><div class="map-legend"><span><i class="dot office"></i> Отделы БПСД (6)</span><span><i class="dot leisure"></i> Кафе и досуг</span><span><i class="dot home"></i> Жильё</span><span><i class="dot mark"></i> Достопримечательности</span><span><i class="dot secret"></i> Тайная точка (только Орден)</span></div>`;}
  function renderCharacter(){const st=s();const p=st.player;const stats=Object.entries(st.stats).map(([k,v])=>`<div class="stat-tile"><small>${({strength:'Сила',agility:'Ловкость',endurance:'Выносливость',intellect:'Интеллект',perception:'Восприятие',will:'Воля',combat:'Бой',medicine:'Медицина',stealth:'Скрытность',charisma:'Харизма'})[k]||k}</small><b>${v}</b></div>`).join('');return `<div class="page-head"><div><div class="eyebrow">PERSONAL FILE / ACTIVE SUBJECT</div><h1>Персонаж</h1><p>Личные данные и параметры развития.</p></div><span class="status-tag">ДОСЬЕ АКТИВНО</span></div><div class="character-profile">${p.image?`<div class="profile-photo"><img src="${esc(p.image)}" alt="Портрет персонажа"></div>`:''}<div class="profile-info"><span class="eyebrow">${esc(p.type)} · ${esc(p.country)}</span><h2>${esc(p.name)}</h2><p>${esc(p.age)} лет · ${esc(p.height)} см · ${esc(p.weight)} кг</p><p>${esc(p.nature)}</p><div class="profile-tags"><span>${esc(p.faction)}</span><span>Специализация: ${esc(p.specialization||'Универсал')}</span>${p.spirit?`<span>Дух: ${esc(p.spirit)}</span>`:''}${p.gift?`<span>Дар: ${esc(p.gift)}</span>`:''}</div><p class="bio-text">${esc(p.bio)}</p></div></div>${p.mark?`<div class="mark-strip"><b>МЕТКА ДУХА</b><span>${esc(p.mark)}</span></div>`:''}<div class="section-heading"><h2>Характеристики</h2><span>РАЗВИТИЕ ЧЕРЕЗ ДЕЙСТВИЯ</span></div><div class="stats-grid">${stats}</div><div class="section-heading"><h2>Имущество</h2><span>НА СТАРТЕ ИСТОРИИ</span></div><div class="asset-grid"><div><small>Жильё</small><b>${p.home?esc(OD_WORLD.getPlace(p.home)?.name||'Указано'):'Нет / служебное размещение'}</b></div><div><small>Автомобиль</small><b>${esc(p.car||'Нет')}</b></div><div><small>Оружие</small><b>${esc(p.weapon||'Не указано')}</b></div><div><small>Деньги</small><b>${st.money} €</b></div></div>`;}
  function renderInventory(){const st=s();return `<div class="page-head"><div><div class="eyebrow">EQUIPMENT / SUPPLIES</div><h1>Инвентарь</h1><p>Предметы, ресурсы и снаряжение персонажа.</p></div><span class="status-tag">${st.inventory.reduce((a,b)=>a+b.qty,0)} ПРЕДМЕТОВ</span></div><div class="inventory-grid">${st.inventory.length?st.inventory.map(i=>`<div class="inventory-item"><span class="item-symbol">${({water:'◒',sandwich:'▰',bandage:'✚',mineral:'◆',medkit:'✚'})[i.id]||'▣'}</span><div><b>${esc(i.name)}</b><small>Количество: ${i.qty}</small></div>${i.id==='water'?'<button data-action="drink">Использовать</button>':i.id==='sandwich'?'<button data-action="eat">Использовать</button>':i.id==='mineral'?'<button data-action="mineral">Принять</button>':''}</div>`).join(''):'<p class="muted">Инвентарь пуст.</p>'}</div><div class="section-heading"><h2>Полевой магазин</h2><span>ПРОДАЖА СНАРЯЖЕНИЯ</span></div><div class="shop-grid">${[{id:'sandwich',name:'Сэндвич',price:8,desc:'Восстанавливает голод.'},{id:'water',name:'Бутылка воды',price:4,desc:'Восстанавливает жажду.'},{id:'mineral',name:'Минеральная смесь',price:22,desc:'Для регенерации одержимых.'},{id:'bandage',name:'Бинт',price:15,desc:'Восстанавливает здоровье в бою.'},{id:'medkit',name:'Аптечка',price:55,desc:'Медицинский запас.'}].map(i=>`<div class="shop-item"><div><b>${i.name}</b><small>${i.desc}</small></div><span>${i.price} €</span><button data-buy="${i.id}">Купить</button></div>`).join('')}</div>`;}
  function renderCombat(){const c=s().combat,encounter=s().encounter;if(!c)return `<div class="page-head"><div><div class="eyebrow">ENCOUNTER / ROLEPLAY CONFLICT</div><h1>Столкновения</h1><p>Здесь нет кнопки случайного боя. Сначала нужно встретить противника, вступить с ним в контакт или спровоцировать конфликт, а затем отдельно решить напасть.</p></div><span class="status-tag">RP RULES</span></div><div class="combat-intro"><div class="combat-warning">…</div><h2>${encounter?'Есть контакт: '+esc(encounter.name):'Пока нет противника'}</h2><p>${encounter?`Вы обнаружили конкретную цель (${esc(encounter.kind==='walker'?'ходячий':'человек')}). Бой не начнётся, пока вы сами не напишете, что нападаете.`:'Чтобы найти цель, опишите поиск ходячего в опасном месте или начните социальный конфликт с конкретным персонажем. После появления цели напишите, что атакуете.'}</p><button class="btn secondary" data-tab="world">Вернуться к RP-сцене →</button></div>`;
    return `<div class="page-head"><div><div class="eyebrow">ENCOUNTER / TURN ${c.turn}</div><h1>Бой</h1><p>${esc(c.enemy.name)} · ${esc(c.enemy.size)} · ${esc(c.enemy.kind==='walker'?'Ходячий':'Человек')}</p></div><span class="status-tag danger">БОЙ ИДЁТ</span></div><div class="enemy-panel"><div class="enemy-icon">⚠</div><div class="enemy-info"><span class="eyebrow">HOSTILE ENTITY · ${esc(c.enemy.id)}</span><h2>${esc(c.enemy.name)}</h2><p>${esc(c.enemy.description)}</p><div class="enemy-metrics"><span>Здоровье <b>${Math.max(0,c.enemy.hp)}</b></span><span>Сила <b>${c.enemy.strength}</b></span><span>Агрессия <b>${c.enemy.aggression}%</b></span><span>Способность <b>${esc(c.enemy.ability)}</b></span></div><div class="need-track enemy-track"><i style="width:${Math.max(0,Math.min(100,c.enemy.hp/(c.enemy.hp+38)*100))}%"></i></div></div></div><div class="combat-log">${c.log.slice().reverse().map((line,i)=>`<p class="${i===0?'latest':''}">${esc(line)}</p>`).join('')}</div><div class="combat-actions"><button data-combat="strike">Ударить</button>${s().player.type==='Одержимый'?'<button data-combat="gift">Использовать Дар</button>':''}<button data-combat="guard">Защищаться</button><button data-combat="item">Использовать бинт</button><button class="escape" data-combat="escape">Попытаться сбежать</button></div>`;}
  function renderJobs(){const can=OD_SURVIVAL.canWork();const st=s();return `<div class="page-head"><div><div class="eyebrow">WORK / MONEY / DAILY NEEDS</div><h1>Экономика и работа</h1><p>Деньги нужны для жилья, еды, воды, медицины и снаряжения.</p></div><span class="money-tag">${st.money} €</span></div>${can?`<div class="job-intro"><h2>Работа для свободных жителей</h2><p>Выберите место работы. После трудоустройства можно выполнять смены и получать оплату.</p></div><div class="job-grid">${OD_DATA.jobs.map(j=>`<div class="job-card"><span>${esc(OD_WORLD.getPlace(j.place)?.name||'Город')}</span><h3>${esc(j.name)}</h3><p>${esc(j.desc)}</p><div><b>${j.pay} €</b><small>за смену · 4 часа</small></div><button data-job="${j.id}" class="${st.jobId===j.id?'selected':''}">${st.jobId===j.id?'Выбрано':'Выбрать работу'}</button></div>`).join('')}</div><div class="work-shift"><div><b>Текущая работа</b><small>${st.jobId?esc(OD_SURVIVAL.findJob(st.jobId).name):'Не выбрана'}</small></div><button class="btn primary" data-action="work">Отработать смену →</button></div>`:`<div class="restricted-card"><span class="lock-symbol">▣</span><h2>Обычная работа недоступна</h2><p>${st.player.faction==='БПСД'?'Сотрудник БПСД получает обеспечение и действует в рамках службы.':'Участники Ордена не могут официально работать в городе.'} Система трудоустройства доступна персонажам без фракции.</p></div>`}<div class="section-heading"><h2>Экономические правила</h2><span>БАЗОВАЯ СИСТЕМА</span></div><div class="economy-notes"><p><b>Расходы:</b> еда, вода, аренда, транспорт, лечение и боеприпасы.</p><p><b>Доход:</b> смены на обычной работе, награды за задания и события.</p><p><b>Валюта:</b> евро (€). Цены игровых заведений указаны в меню покупки.</p></div>`;}
  function renderTraining(){return `<div class="page-head"><div><div class="eyebrow">PHYSICAL DEVELOPMENT / SKILL CHECK</div><h1>Тренировки</h1><p>Опишите занятие своими словами. Локальная система оценит длительность и тип нагрузки.</p></div><span class="status-tag">ЗАНЯТИЯ: ${s().training.sessions}</span></div><div class="training-card"><div class="training-illustration">↗</div><h2>Опишите вашу тренировку</h2><p>Пример: «30 минут бегал, сделал 20 отжиманий, 15 приседаний и растяжку». Чем подробнее описание, тем точнее оценка.</p><form id="training-form"><textarea name="training" rows="4" placeholder="Сегодня я..." required></textarea><button class="btn primary" type="submit">Оценить тренировку →</button></form><div class="training-result"><small>ПОСЛЕДНИЙ РЕЗУЛЬТАТ</small><p>${esc(s().training.lastResult)}</p></div></div><div class="section-heading"><h2>Что развивается</h2><span>НАВЫКИ ПЕРСОНАЖА</span></div><div class="training-types"><div><b>Сила</b><small>Отжимания, приседания, силовые упражнения.</small></div><div><b>Выносливость</b><small>Бег, ходьба, велосипед, плавание.</small></div><div><b>Ловкость</b><small>Растяжка, йога, подвижность.</small></div><div><b>Боевые навыки</b><small>Бокс, спарринг, единоборства.</small></div><div><b>Воля</b><small>Дыхательные практики и концентрация.</small></div></div>`;}
  function renderDevices(){const st=s(),device=st.device||'phone',site=OD_DEVICES.get(st.browserSite)||OD_DEVICES.available().find(x=>x.device.includes(device));const devices=[['phone','Телефон','◉','Всегда с собой'],['laptop','Ноутбук','▣','Браузер и документы'],['watch','Часы','◷','Время и уведомления']];const sites=OD_DEVICES.available().filter(x=>x.device.includes(device));const current=site&&site.device.includes(device)?site:null;return `<div class="page-head"><div><div class="eyebrow">PERSONAL ELECTRONICS / 2023</div><h1>Устройства</h1><p>Телефон, ноутбук и часы. Сайты и публикации — внутриигровые, сохранены локально.</p></div><span class="status-tag">3 УСТРОЙСТВА</span></div><div class="device-switch">${devices.map(([id,name,icon,desc])=>`<button data-device="${id}" class="device-card ${device===id?'active':''}"><b>${icon} ${name}</b><small>${desc}</small></button>`).join('')}</div>${device==='watch'?`<div class="watch-face"><small>BERLIN · 2023</small><strong>${String(st.hour).padStart(2,'0')}:${String(st.minute).padStart(2,'0')}</strong><b>${dateLabel(st)}</b><p>Уведомления: ${st.rpTurns?.length?`последний ход мастера сохранён`:'нет новых сообщений'}</p></div>`:`<div class="browser-window"><div class="browser-top"><span class="browser-lights">● ● ●</span><span class="browser-address">${current?esc(current.url):'about:blank'}</span><span>LOCAL WEB</span></div><div class="browser-layout"><nav class="site-bookmarks">${sites.map(x=>`<button data-site="${x.id}" class="${current?.id===x.id?'active':''}"><b>${esc(x.name)}</b><small>${esc(x.category)}</small></button>`).join('')}</nav><article class="site-article">${current?`<div class="eyebrow">${esc(current.category)} · ${esc(current.url)}</div><h2>${esc(current.title)}</h2><small>${esc(current.date)}</small><p>${esc(current.body)}</p><div class="site-footnote">Внутриигровой информационный ресурс. Дата мира: 2023 год.</div>`:'<h2>Локальный браузер</h2><p>Выберите закладку. Здесь публикуются новости города, объявления, внутренние сводки и слухи.</p>'}</article></div></div>`}<div class="section-heading"><h2>Для чего нужны устройства</h2><span>ИГРОВЫЕ ФУНКЦИИ</span></div><div class="device-notes"><p><b>Телефон:</b> звонки, сообщения, карта и новости на ходу.</p><p><b>Ноутбук:</b> архивы, сайты, служебные документы и форумы.</p><p><b>Часы:</b> время, дата и короткие уведомления.</p></div>`;}
  function renderSettings(){return `<div class="page-head"><div><div class="eyebrow">LOCAL SYSTEM / SAVE MANAGEMENT</div><h1>Система</h1><p>Настройки локального прохождения и сохранения.</p></div><span class="status-tag">OFFLINE</span></div><div class="settings-card"><h2>Сохранение</h2><p>Прогресс хранится в локальном хранилище браузера на этом устройстве.</p><div class="settings-actions"><button class="btn secondary" data-action="save">Сохранить сейчас</button><button class="btn secondary" data-action="export">Экспорт сохранения</button><label class="btn secondary import-label">Импорт сохранения<input type="file" id="import-save" accept="application/json"></label></div></div><div class="settings-card"><h2>О проекте</h2><p>«Одержимые» — офлайн-прототип текстовой RPG. Свободный ввод разбирается локальными правилами и ключевыми словами. Интернет и внешний ИИ не используются.</p><p>Сейчас доступны создание персонажа, распределение по фракциям, карта Берлина, потребности, работа, тренировки, база NPC и пошаговые бои.</p></div><div class="settings-card danger-zone"><h2>Сброс истории</h2><p>Удалит персонажа и сохранение на этом устройстве. Это действие нельзя отменить без резервной копии.</p><button class="btn danger" data-action="reset">Начать новую историю</button></div>`;}
  function chooseWeighted(options,scoreFn){const scored=options.map(o=>({o,w:Math.max(1,scoreFn(o)+Math.random()*8)}));const total=scored.reduce((a,x)=>a+x.w,0);let r=Math.random()*total;for(const x of scored){r-=x.w;if(r<=0)return x.o;}return options[0];}
  function chooseTeam(answers,mode){const p=player();const text=answers.join(' ').toLowerCase();if(p.faction!=='БПСД')return null;
    const stats=s().stats;const spec=p.specialization||'Универсал';
    if(p.type==='Человек'){
      const keys={lead:['лидер','команд','приказ','руковод'],stealth:['наблюд','тихо','скрыт','осторож'],combat:['атак','в бой','оруж','сраж'],care:['помощ','спасти','эвакуац','защитить'],analysis:['план','анализ','изуч','допрос']};
      return chooseWeighted(OD_DATA.humanTeams,t=>{let v=4;if(keys.combat.some(k=>text.includes(k))&&['Молот','Ястреб','Таран'].includes(t.name))v+=8;if(keys.stealth.some(k=>text.includes(k))&&['Штиль','Спектр','Контур'].includes(t.name))v+=7;if(keys.care.some(k=>text.includes(k))&&['Барьер','Маяк','Форпост'].includes(t.name))v+=7;if(keys.analysis.some(k=>text.includes(k))&&['Вектор','Контур','Рубеж'].includes(t.name))v+=7;if(keys.lead.some(k=>text.includes(k))&&['Сокол','Гранит','Рубеж'].includes(t.name))v+=5;if(spec==='Ближний бой'&&['Молот','Ястреб','Таран'].includes(t.name))v+=7;if(spec==='Скрытность'&&['Штиль','Спектр','Контур'].includes(t.name))v+=7;if(spec==='Медицина'&&['Барьер','Маяк','Форпост'].includes(t.name))v+=7;if(spec==='Аналитика'&&['Вектор','Контур','Рубеж'].includes(t.name))v+=7;if(spec==='Следопытство'&&['Ястреб','Форпост','Спектр'].includes(t.name))v+=6;if(spec==='Переговоры'&&['Сокол','Маяк','Рубеж'].includes(t.name))v+=6;if(stats.strength+stats.combat>25&&['Молот','Ястреб','Таран'].includes(t.name))v+=4;if(stats.stealth+stats.agility>25&&['Штиль','Спектр','Контур'].includes(t.name))v+=4;if(stats.medicine+stats.intellect>20&&['Барьер','Маяк','Вектор'].includes(t.name))v+=3;if(stats.charisma+stats.will>22&&['Сокол','Гранит','Рубеж'].includes(t.name))v+=3;return v;});
    }
    const knownSpirit=OD_DATA.spirits.find(x=>x.name.toLowerCase()===String(p.spirit||'').toLowerCase());
    const spiritText=`${p.spirit||''} ${p.gift||''}`.toLowerCase();
    let inferredSkill=knownSpirit?.skill||'универсал';
    if(!knownSpirit){
      if(/сил|удар|боев|кост|ярост|кров|оруж|ата|разруш/.test(spiritText))inferredSkill='ближний бой';
      else if(/тень|скры|невид|тише|бесшум|маск|исчез/.test(spiritText))inferredSkill='скрытность';
      else if(/леч|исцел|защит|барьер|щит|контрол|энерг|стих|огн|вод|электр|лед|лёд/.test(spiritText))inferredSkill='контроль';
      else if(/след|запах|слух|звер|охот|выжив|природ|живот/.test(spiritText))inferredSkill='следопытство';
    }
    const all=[...OD_DATA.mixedTeams,...OD_DATA.possessedTeams];
    return chooseWeighted(all,t=>{let v=4;if(inferredSkill==='ближний бой'||inferredSkill==='сила'){if(['Клин','Таран','Кремень'].includes(t.name))v+=8;}if(inferredSkill==='скрытность'){if(['Ворон','Ночной дозор','Кобра'].includes(t.name))v+=8;}if(inferredSkill==='контроль'){if(['Пепел','Гриф','Рой'].includes(t.name))v+=6;}if(inferredSkill==='выживание'||inferredSkill==='следопытство'){if(['Шрам','Волк','Кремень'].includes(t.name))v+=6;}if(spec==='Ближний бой'&&['Клин','Таран','Кремень'].includes(t.name))v+=7;if(spec==='Скрытность'&&['Ворон','Кобра','Ночной дозор'].includes(t.name))v+=7;if(spec==='Медицина'&&['Гриф','Пепел','Рой'].includes(t.name))v+=4;if(spec==='Аналитика'&&['Гриф','Ворон','Пепел'].includes(t.name))v+=5;if(spec==='Следопытство'&&['Волк','Шрам','Кобра'].includes(t.name))v+=6;if(spec==='Переговоры'&&['Гриф','Клин','Рой'].includes(t.name))v+=3;if(stats.strength+stats.combat>25&&['Клин','Таран','Кремень'].includes(t.name))v+=4;if(stats.stealth+stats.agility>25&&['Ворон','Кобра','Ночной дозор'].includes(t.name))v+=4;if(stats.perception+stats.intellect>25&&['Гриф','Пепел','Шрам'].includes(t.name))v+=3;if(t.type==='possessed'&&['Вар','Костолом','Зверь'].includes(p.spirit))v+=4;if(t.type==='mixed'&&['Тень','Пепел','Шёпот'].includes(p.spirit))v+=3;if(text.includes('один')&&t.type==='possessed')v+=2;return v;});
  }
  function applyTeam(team){const st=s();if(!team){OD_STATE.set({teamId:null});return;}
    let ids=team.type==='mixed'?team.members:team.type==='possessed'?[...team.members]:team.members;
    if(team.type==='human'){ids=[...team.members];ids[ids.length-1]='player';}
    else if(team.type==='mixed'){ids=[...team.members];ids[ids.length-1]='player';}
    else if(team.type==='possessed'){ids=[...team.members];ids[ids.length-1]='player';}
    team.runtimeMembers=ids;
    OD_STATE.set({teamId:team.id,teamOverride:ids});
  }
  function beginBPSD(mode,answers=[]){const p=player();const team=chooseTeam(answers,mode);applyTeam(team);if(p.type==='Одержимый')OD_STATE.update(st=>{st.player.home=null;});if(mode==='late'){
      const loc=p.type==='Человек'?(p.home||'quarters-bpsd'):'quarters-bpsd';OD_STATE.set({step:'game',started:true,startMode:'late',location:loc,flags:{...s().flags,interviewDone:true,firstBriefing:true}});OD_STATE.addLog(`Вы проснулись уже в отряде ${team?.name||''}. Служба продолжается.`);OD_GM.opening();tab='world';render();return;
    }
    OD_STATE.set({step:'briefing',started:true,startMode:'early',flags:{...s().flags,interviewDone:true}});OD_STATE.addLog(`Допрос завершён. Вы распределены в отряд ${team?.name||'самостоятельная служба'}.`);render();}
  async function saveDossier(form){const fd=new FormData(form);const type=s().characterType;let image=fd.get('imageUrl')?.trim()||pendingAvatar;const file=$('image-file')?.files?.[0];if(file){image=await readImage(file);}const faction=fd.get('faction');if(type==='Человек'&&faction==='Орден'){setNotice('Люди не могут вступать в Орден.');return;}
    const spirit=(fd.get('spirit')||'').trim();if(type==='Одержимый'){const existingHost=OD_DATA.findSpiritHost(spirit);if(existingHost){const hostType=String(existingHost.id).startsWith('walker-')?'ходячий':'одержимый';setNotice(`Дух «${spirit}» уже связан с носителем: ${existingHost.name} (${hostType}). У каждого духа может быть только один носитель — человек или животное.`);return;}}let home=fd.get('home')||null;if(faction==='Орден'||(type==='Одержимый'&&faction==='БПСД'))home=null;
    const person={id:'player',type,name:`${fd.get('firstName').trim()} ${fd.get('lastName').trim()}`,firstName:fd.get('firstName').trim(),lastName:fd.get('lastName').trim(),age:Number(fd.get('age')),weight:Number(fd.get('weight')),height:Number(fd.get('height')),country:fd.get('country'),specialization:fd.get('specialization')||'Универсал',nature:fd.get('nature').trim(),bio:fd.get('bio').trim(),faction,spirit:type==='Одержимый'?spirit:null,gift:type==='Одержимый'?fd.get('gift'):null,mark:type==='Одержимый'?fd.get('mark'):null,home,car:fd.get('car').trim(),weapon:fd.get('weapon').trim(),image};
    OD_STATE.update(st=>{st.player=person;st.money=Math.max(0,Number(fd.get('money'))||0);st.step='start';st.needs={hunger:90,thirst:90,energy:90,health:100,sanity:100,minerals:90};st.teamId=null;st.location=faction==='Орден'?'order-den':faction==='БПСД'?(type==='Одержимый'?'office-1':home||'quarters-bpsd'):home||'mitte';});OD_STATE.save();pendingAvatar='';render();}
  function readImage(file){return new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const scale=Math.min(1,700/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.72));};img.onerror=()=>resolve(reader.result);img.src=reader.result;};reader.onerror=()=>resolve('');reader.readAsDataURL(file);});}
  function submitInterview(form){const fd=new FormData(form);beginBPSD('early',[fd.get('q1')||'',fd.get('q2')||'',fd.get('q3')||'']);}
  function goGame(){const st=s();if(st.player.faction==='Орден'){OD_STATE.set({location:'order-den',step:'game',started:true,flags:{...st.flags,orderIntro:true}});OD_STATE.addLog('Вы прибыли в логово Ордена. Вар готовит своих последователей к захвату мира.');}else{const loc=st.player.type==='Одержимый'?'quarters-bpsd':(st.player.home||'quarters-bpsd');OD_STATE.set({location:loc,step:'game',started:true,flags:{...st.flags,firstBriefing:true}});OD_STATE.addLog(`Вы прибыли в ${st.player.type==='Одержимый'?'служебное помещение БПСД':`расположение отряда ${teamById(st.teamId)?.name||''}`}. Впереди знакомство с командой.`);}OD_GM.opening();tab='world';render();}
  function actionResult(r){setNotice(r?.message||String(r));render();}
  app.addEventListener('click',e=>{
    const btn=e.target.closest('button');const mapPoint=e.target.closest('.map-point');
    if(mapPoint){const id=mapPoint.dataset.place;const r=OD_WORLD.travel(id);setNotice(r.message);tab='map';render();return;}
    if(!btn)return;
    if(btn.dataset.action){const a=btn.dataset.action;switch(a){
      case 'choose-human':OD_STATE.set({step:'type',characterType:'Человек'});break;
      case 'choose-possessed':OD_STATE.set({step:'type',characterType:'Одержимый'});break;
      case 'back-landing':OD_STATE.set({step:'landing'});break;
      case 'back-type':OD_STATE.set({step:'type'});break;
      case 'to-dossier':OD_STATE.set({step:'dossier'});break;
      case 'back-dossier':OD_STATE.set({step:'dossier'});break;
      case 'back-start':OD_STATE.set({step:'start'});break;
      case 'start-early':OD_STATE.set({step:'interview'});break;
      case 'start-late':beginBPSD('late');return;
      case 'start-order':OD_STATE.set({step:'game',started:true,startMode:'order',location:'order-den'});OD_STATE.addLog('Вы вошли в логово Ордена. Вар собирает одержимых под своим знаменем.');OD_GM.opening();tab='world';break;
      case 'start-free':OD_STATE.set({step:'game',started:true,startMode:'free',location:player().home||'mitte'});OD_STATE.addLog('Вы начинаете самостоятельную жизнь в Берлине.');OD_GM.opening();tab='world';break;
      case 'arrive-team':goGame();return;
      case 'save':OD_STATE.save();setNotice('Прогресс сохранён на этом устройстве.');break;
      case 'eat':actionResult(OD_SURVIVAL.eat());return;
      case 'drink':actionResult(OD_SURVIVAL.drink());return;
      case 'rest':actionResult(OD_SURVIVAL.rest());return;
      case 'mineral':actionResult(OD_SURVIVAL.useMineral());return;
      case 'talk':setNotice(OD_INTERPRETER.talk('поговорить'));render();return;
      case 'explore':setNotice(OD_INTERPRETER.handle('осмотреть окрестности'));render();return;
      case 'work':actionResult(OD_SURVIVAL.work());return;
      case 'team-details':showTeamDetails=!showTeamDetails;break;
      case 'export':exportSave();return;
      case 'reset':if(confirm('Точно начать новую историю? Текущее сохранение будет удалено.')){OD_STATE.reset();pendingAvatar='';showTeamDetails=false;tab='world';}break;
    }render();return;}
    if(btn.dataset.tab){tab=btn.dataset.tab;render();return;}
    if(btn.dataset.rpAction){setNotice(OD_INTERPRETER.handle(btn.dataset.rpAction));render();return;}
    if(btn.dataset.device){OD_STATE.set({device:btn.dataset.device});tab='devices';render();return;}
    if(btn.dataset.site){const result=OD_DEVICES.open(btn.dataset.site);setNotice(result.message);tab='devices';render();return;}
    if(btn.dataset.travel){const r=OD_WORLD.travel(btn.dataset.travel);setNotice(r.message);render();return;}
    if(btn.dataset.filter){OD_STATE.set({mapFilter:btn.dataset.filter});render();return;}
    if(btn.dataset.buy){actionResult(OD_SURVIVAL.buy(btn.dataset.buy));return;}
    if(btn.dataset.job){actionResult(OD_SURVIVAL.takeJob(btn.dataset.job));return;}
    if(btn.dataset.combat){actionResult(OD_COMBAT.act(btn.dataset.combat));return;}
  });
  app.addEventListener('submit',async e=>{
    e.preventDefault();const form=e.target;
    if(form.id==='dossier-form'){await saveDossier(form);return;}
    if(form.id==='interview-form'){submitInterview(form);return;}
    if(form.id==='free-action-form'){const text=new FormData(form).get('action');setNotice(OD_INTERPRETER.handle(text));render();return;}
    if(form.id==='training-form'){const text=new FormData(form).get('training');setNotice(OD_SURVIVAL.train(text).message);render();return;}
  });
  app.addEventListener('change',e=>{
    if(e.target.id==='image-file'){const f=e.target.files?.[0];if(f){readImage(f).then(data=>{pendingAvatar=data;const img=$('portrait-preview');if(img){img.src=data;img.hidden=false;const empty=$('portrait-empty');if(empty)empty.hidden=true;}});}}
    if(e.target.id==='image-url'){const url=e.target.value.trim();if(url){pendingAvatar=url;const img=$('portrait-preview');if(img){img.src=url;img.hidden=false;const empty=$('portrait-empty');if(empty)empty.hidden=true;}}}
    if(e.target.id==='faction-select'){const note=$('faction-note');if(note)note.textContent=factionDescription(e.target.value);const rule=$('home-rule');const homeSelect=$('home-select');const locked=s().characterType==='Одержимый'&&(e.target.value==='БПСД'||e.target.value==='Орден');if(homeSelect)homeSelect.disabled=locked;if(rule)rule.textContent=e.target.value==='Орден'?'Членам Ордена жильё заменяет тайное логово.':s().characterType==='Одержимый'&&e.target.value==='БПСД'?'Одержимый сотрудник БПСД не может иметь собственное жильё.':'Можно указать жильё, доступное персонажу.';}
    if(e.target.id==='import-save'){const file=e.target.files?.[0];if(file){const r=new FileReader();r.onload=()=>{try{const data=JSON.parse(r.result);localStorage.setItem('oderzhimye-save-v1',JSON.stringify(data));OD_STATE.load();setNotice('Сохранение импортировано.');render();}catch(_){setNotice('Файл сохранения повреждён.');render();}};r.readAsText(file);}}
  });
  function exportSave(){const blob=new Blob([JSON.stringify(s(),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='oderzhimye-save.json';a.click();URL.revokeObjectURL(url);setNotice('Файл сохранения подготовлен.');}
  topbar.addEventListener('click',e=>{if(e.target.closest('[data-action="save"]')){OD_STATE.save();setNotice('Прогресс сохранён.');}if(e.target.closest('[data-action="home"]')){tab='world';render();}});
  OD_STATE.load();
  if(s().started&&s().player)s().step='game';
  if('serviceWorker' in navigator && (location.protocol==='http:' || location.protocol==='https:')){navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('Offline cache is unavailable',err));}
  render();
})();
